#include <string.h>
#include <re.h>
#include "slcacert.h"

#define DEBUG_MODULE "slcacert"
#define DEBUG_LEVEL 5
#include <re_dbg.h>

/* generated by CMake from cacert.pem (sl_cacert_data.c) */
extern const char sl_cacert_pem_data[];

static const char pem_begin[] = "-----BEGIN CERTIFICATE-----";
static const char pem_end[]   = "-----END CERTIFICATE-----";


const char *sl_cacert_pem(void)
{
	return sl_cacert_pem_data;
}


/**
 * Add all embedded CA certificates to a TLS context
 *
 * tls_add_capem() only reads the first certificate of a PEM string, so the
 * bundle is split and every certificate is added on its own.
 *
 * @param tls TLS context
 *
 * @return 0 if success, otherwise errorcode
 */
int sl_cacert_add(struct tls *tls)
{
	const char *p = sl_cacert_pem_data;
	unsigned added = 0, failed = 0;

	if (!tls)
		return EINVAL;

	while ((p = strstr(p, pem_begin)) != NULL) {
		const char *end = strstr(p, pem_end);
		char *cert;
		size_t len;

		if (!end)
			break;

		end += sizeof(pem_end) - 1;
		len  = end - p;

		cert = mem_alloc(len + 1, NULL);
		if (!cert)
			return ENOMEM;

		memcpy(cert, p, len);
		cert[len] = '\0';

		if (tls_add_capem(tls, cert))
			++failed;
		else
			++added;

		mem_deref(cert);
		p = end;
	}

	if (failed)
		DEBUG_WARNING("%u CA certificates could not be added\n",
			      failed);

	DEBUG_INFO("%u CA certificates added\n", added);

	return added ? 0 : ENOENT;
}


/**
 * Allocate an HTTP client which verifies the server with the embedded CA
 * certificates
 *
 * @param clip Pointer to allocated HTTP client
 * @param dnsc DNS client
 *
 * @return 0 if success, otherwise errorcode
 */
int sl_http_client_alloc(struct http_cli **clip, struct dnsc *dnsc)
{
	struct http_cli *cli = NULL;
	struct tls *tls = NULL;
	int err;

	if (!clip)
		return EINVAL;

	err = http_client_alloc(&cli, dnsc);
	if (err)
		return err;

	err = http_client_get_tls(cli, &tls);
	if (err)
		goto out;

	err = sl_cacert_add(tls);

 out:
	if (err)
		mem_deref(cli);
	else
		*clip = cli;

	return err;
}
